def min_window_sequence(s, t):
    n, m = len(s), len(t)
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for j in range(m + 1):
        dp[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s[i-1] == t[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = dp[i-1][j] + 1
    best = n + 1
    for i in range(m, n + 1):
        if dp[i][m] < best:
            best = dp[i][m]
    return s[best - 1 - m + 1:best] if best <= n else ''
