For count islands bfs I will sweep the grid and BFS each unvisited '1'.

```python
def num_islands(grid):
    if not grid: return 0
    m, n = len(grid), len(grid[0])
    seen = [[False] * n for _ in range(m)]
    def bfs(r, c):
        q = [(r, c)]
        seen[r][c] = True
        while q:
            x, y = q.pop()
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and not seen[nx][ny] and grid[nx][ny] == '1':
                    seen[nx][ny] = True
                    q.append((nx, ny))
    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and not seen[i][j]:
                count += 1
                bfs(i, j)
    return count
```

