    def __init__(self, capacity):
        self.cap = capacity
        self.cache = {}
    def get(self, k):
        if k not in self.cache:
            return -1
        v = self.cache.pop(k)
        self.cache[k] = v
        return v
    def put(self, k, v):
        if k in self.cache:
