from typing import Iterator

class Range:
    """A numeric range similar to range(start, stop, step).

    Examples:
        >>> r = Range(0, 10, 2)
        >>> r.length
        5
        >>> list(r.iter_values())
        [0, 2, 4, 6, 8]
        >>> Range(5, 5, 1).length
        0
    """
    def __init__(self, start: int, stop: int, step: int = 1) -> None:
        if step == 0:
            raise ValueError("step must be non-zero")
        self.start: int = start
        self.stop: int = stop
        self.step: int = step

    @property
    def length(self) -> int:
        if self.step > 0:
            if self.start >= self.stop:
                return 0
            return (self.stop - self.start + self.step - 1) // self.step
        if self.start <= self.stop:
            return 0
        return (self.start - self.stop + (-self.step) - 1) // (-self.step)

    def iter_values(self) -> Iterator[int]:
        if self.step > 0:
            v = self.start
            while v < self.stop:
                yield v
                v += self.step
        else:
            v = self.start
            while v > self.stop:
                yield v
                v += self.step

