from typing import Callable, Any, List

class EmitterWithRemoveAll:
    """Emitter that supports removing all listeners for an event."""
    def __init__(self) -> None:
        self._handlers: dict = {}

    def on(self, event: str, handler: Callable[..., None]) -> None:
        self._handlers.setdefault(event, []).append(handler)

    def remove_all(self, event: str) -> int:
        """Remove all listeners for event; returns count removed.

        Examples:
            >>> e = EmitterWithRemoveAll()
            >>> e.on('x', lambda: None)
            >>> e.remove_all('x')
            1
        """
        return len(self._handlers.pop(event, []))

    def emit(self, event: str, *args: Any) -> None:
        for h in list(self._handlers.get(event, [])):
            h(*args)

