```python
def add_ops(num, target):
    out = []
    def rec(i, path, value, last):
        if i == len(num):
            if value == target: out.append(path)
            return
        for j in range(i, len(num)):
            if j > i and num[i] == '0': break
            cur = int(num[i:j+1])
            if i == 0:
                rec(j + 1, path + str(cur), cur, cur)
            else:
                rec(j + 1, path + '+' + str(cur), value + cur, cur)
                rec(j + 1, path + '-' + str(cur), value - cur, -cur)
                rec(j + 1, path + '*' + str(cur), value - last + last * cur, last * cur)
    rec(0, '', 0, 0)
    return out
