```python
def order_of_largest_plus(n, mines):
    banned = {tuple(m) for m in mines}
    grid = [[0] * n for _ in range(n)]
    for i in range(n):
        left = right = up = down = 0
        for j in range(n):
            left = 0 if (i, j) in banned else left + 1
            grid[i][j] = max(grid[i][j], left)
        for j in range(n - 1, -1, -1):
            right = 0 if (i, j) in banned else right + 1
            grid[i][j] = max(grid[i][j], right)
        for j in range(n):
            up = 0 if (j, i) in banned else up + 1
            grid[j][i] = max(grid[j][i], up)
        for j in range(n - 1, -1, -1):
            down = 0 if (j, i) in banned else down + 1
            grid[j][i] = max(grid[j][i], down)
    return max(max(row) for row in grid)
