class Card:
    """A playing card whose length equals its rank value.

    Examples:
        >>> Card('A').__len__()
        1
        >>> len(Card('K'))
        13
        >>> Card('Q')
        Card(rank='Q')
    """
    _rank_value: int

    def __init__(self, rank: str) -> None:
        if not isinstance(rank, str) or not rank:
            raise ValueError("rank must be a non-empty string")
        table = {"A": 1, "J": 11, "Q": 12, "K": 13}
        if rank.upper() in table:
            self._rank_value = table[rank.upper()]
            self.rank: str = rank.upper()
        else:
            try:
                value = int(rank)
            except ValueError as exc:
                raise ValueError("rank must be 1..10, A, J, Q, K") from exc
            if not (2 <= value <= 10):
                raise ValueError("rank must be 1..10, A, J, Q, K")
            self._rank_value = value
            self.rank = str(value)

    def __len__(self) -> int:
        return self._rank_value

    def __repr__(self) -> str:
        return f"Card(rank='{self.rank}')"

