DFS from (0,0). Mark visited; try 4 directions. Backtrack.

```python
def rat_maze(maze):
    n = len(maze)
    sol = [[0] * n for _ in range(n)]
    def dfs(i, j):
        if i == n - 1 and j == n - 1 and maze[i][j] == 1:
            sol[i][j] = 1
            return True
        if 0 <= i < n and 0 <= j < n and maze[i][j] == 1 and sol[i][j] == 0:
            sol[i][j] = 1
            for di, dj in ((1, 0), (0, 1), (-1, 0), (0, -1)):
                if dfs(i + di, j + dj):
                    return True
            sol[i][j] = 0
        return False
    dfs(0, 0)
    return sol
