from collections import deque

def level_order(graph, start):
    """Return nodes visited in BFS order starting from start."""
    seen = {start}
    order = []
    q = deque([start])
    while q:
        v = q.popleft()
        order.append(v)
        for nb in graph.get(v, ()):
            if nb not in seen:
                seen.add(nb)
                q.append(nb)
    return order

Classic DP. dp[i][j] = edit distance of s[:i] and t[:j]. Transitions: insert/delete/replace.

```python
def edit_distance(s, t):
    m, n = len(s), len(t)
    dp = [[i + j if i * j == 0 else 0 for j in range(n + 1)] for i in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i-1] == t[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
    return dp[m][n]
