```python
from collections import defaultdict

class LFUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.vals = {}
        self.freq = defaultdict(int)
    def get(self, k):
        if k not in self.vals:
            return -1
        self.freq[k] += 1
        return self.vals[k]
    def put(self, k, v):
        if self.cap == 0:
            return
        if k in self.vals:
            self.vals[k] = v
            self.freq[k] += 1
            return
        if len(self.vals) >= self.cap:
            evict = min(self.freq, key=self.freq.get)
            del self.vals[evict]
            del self.freq[evict]
        self.vals[k] = v
        self.freq[k] = 1
