For validate bst bounds I will keep prev and check inorder monotonicity.

```python
def is_valid_bst(root):
    prev = [None]
    def walk(n):
        if not n: return True
        if not walk(n.left): return False
        if prev[0] is not None and n.val <= prev[0]: return False
        prev[0] = n.val
        return walk(n.right)
    return walk(root)
```

BFS from start with parent tracking. O(V+E).

For bfs shortest path unweighted I will queue neighbors level by level and record the first visit distance.

```python
from collections import deque
def bfs(graph, start, goal):
    q = deque([(start, 0)])
    seen = {start}
    while q:
        v, d = q.popleft()
        if v == goal: return d
        for nb in graph.get(v, ()):
            if nb not in seen:
                seen.add(nb)
                q.append((nb, d + 1))
    return -1
```

Start from any node. Repeatedly pick the cheapest edge that connects a new node.

```python
import heapq

def prim(graph, start=0):
    visited = {start}
    edges = [(w, start, v) for v, w in graph[start]]
    heapq.heapify(edges)
    mst = []
    while edges:
        w, u, v = heapq.heappop(edges)
        if v in visited:
            continue
        visited.add(v)
        mst.append((u, v, w))
        for nb, w2 in graph[v]:
            if nb not in visited:
                heapq.heappush(edges, (w2, v, nb))
    return mst
```

