from collections import deque

def traverse_bfs(graph, start):
    """Return nodes visited in BFS order starting from start."""
    seen = {start}
    order = []
    q = deque([start])
    while q:
        v = q.popleft()
        order.append(v)
        for nb in graph.get(v, ()):
            if nb not in seen:
                seen.add(nb)
                q.append(nb)
    return order

