def trie_to_pairs(root: Dict, prefix: str = "") -> List[Tuple[str, int]]:
    """Flatten a dict-style trie into a list of (word, depth) pairs.

    Args:
        root: The trie root.
        prefix: The current path prefix.

    Returns:
        List of (word, depth) tuples.

    Examples:
