class Thermostat:
    """A thermostat storing Celsius with a Fahrenheit view.

    Examples:
        >>> t = Thermostat(0)
        >>> t.fahrenheit
        32.0
        >>> t.celsius = 100
        >>> t.fahrenheit
        212.0
    """
    def __init__(self, celsius: Number = 0) -> None:
        if celsius is None:
            raise TypeError("celsius must be a number")
