For spiral matrix generation I will track top/bottom/left/right bounds and walk them in spiral order.

```python
def spiral(mat):
    out = []
    if not mat: return out
    t, b, l, r = 0, len(mat) - 1, 0, len(mat[0]) - 1
    while t <= b and l <= r:
        for j in range(l, r + 1): out.append(mat[t][j])
        t += 1
        for i in range(t, b + 1): out.append(mat[i][r])
        r -= 1
        if t <= b:
            for j in range(r, l - 1, -1): out.append(mat[b][j])
            b -= 1
        if l <= r:
            for i in range(b, t - 1, -1): out.append(mat[i][l])
            l += 1
    return out
