def dfs_traverse(graph, start):
    """Return nodes visited in DFS preorder starting from start."""
    seen = set()
    order = []
    def walk(v):
        if v in seen:
            return
        seen.add(v)
        order.append(v)
        for nb in graph.get(v, ()):
            walk(nb)
    walk(start)
