class StringBuilder:
    """A growing string buffer with += support.

    Examples:
        >>> sb = StringBuilder()
        >>> sb += "hello"
        >>> sb += " "
        >>> sb += "world"
        >>> str(sb)
        'hello world'
        >>> len(sb)
        11
    """
    def __init__(self) -> None:
