For Count islands in grid ["11000","11000","00100","00011"] (answer 3). I will flood-fill from each unvisited '1'.

```python
def num_islands(grid):
    if not grid: return 0
    m, n = len(grid), len(grid[0])
    seen = [[False] * n for _ in range(m)]
    def bfs(r, c):
        stack = [(r, c)]
        seen[r][c] = True
        while stack:
            i, j = stack.pop()
            for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == '1' and not seen[ni][nj]:
                    seen[ni][nj] = True
                    stack.append((ni, nj))
    count = 0
    for r in range(m):
        for c in range(n):
            if grid[r][c] == '1' and not seen[r][c]:
                bfs(r, c); count += 1
    return count
```

