```python
from collections import deque

def ladder_length(begin, end, words):
    s = set(words)
    queue = deque([(begin, 1)])
    while queue:
        word, depth = queue.popleft()
        if word == end:
            return depth
        for i in range(len(word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                nw = word[:i] + c + word[i+1:]
                if nw in s:
                    s.remove(nw)
                    queue.append((nw, depth + 1))
    return 0
```

Detect cycle in directed graph. Topological sort with indegrees.

```python
from collections import deque

def can_finish(n, prereqs):
    graph = {i: [] for i in range(n)}
    indeg = [0] * n
    for a, b in prereqs:
        graph[b].append(a)
        indeg[a] += 1
    q = deque(i for i in range(n) if indeg[i] == 0)
    visited = 0
    while q:
        u = q.popleft()
        visited += 1
        for v in graph[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                q.append(v)
    return visited == n
