```python
from collections import deque

def bfs_shortest(graph, src, target):
    queue = deque([(src, 0)])
    seen = {src}
    while queue:
        node, dist = queue.popleft()
        if node == target:
            return dist
        for nb in graph.get(node, []):
            if nb not in seen:
                seen.add(nb)
                queue.append((nb, dist + 1))
    return -1
