class CharCounter:
    """Count occurrences of a single character in a body of text.

    Examples:
        >>> c = CharCounter('o')
        >>> c.count_in("onomatopoeia")
        4
        >>> c.count_in("")
        0
        >>> c.count_in("xyz")
        0
    """
