```python
def candy(r):
    n = len(r)
    out = [1] * n
    for i in range(1, n):
        if r[i] > r[i-1]: out[i] = out[i-1] + 1
    for i in range(n - 2, -1, -1):
        if r[i] > r[i+1]: out[i] = max(out[i], out[i+1] + 1)
    return sum(out)
