```python
def num_islands(grid):
    if not grid:
        return 0
    m, n = len(grid), len(grid[0])
    count = 0
    def sink(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or grid[i][j] != '1':
            return
        grid[i][j] = '0'
        for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
            sink(i + di, j + dj)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                sink(i, j)
                count += 1
    return count
